/**
 * Code templates of the generated transformer of a class.
 *
 * Placeholders are written as {{name}}. A placeholder on a line of its own is replaced with every line of
 * the value indented like the placeholder, so nested blocks stay readable in the generated file.
 *
 * @internal
 */
final class Templates
{
    /** @param array<string, string> $variables */
    public static function render(string $template, array $variables): string
    {
        $template = trim($template, "\n");

        foreach ($variables as $name => $value) {
            $template = self::replaceIndented($template, $name, $value);
        }

        return $template;
    }

    private static function replaceIndented(string $template, string $name, string $value): string
    {
        $placeholder = '{{' . $name . '}}';

        $result = preg_replace_callback(
            '/^([ \t]*)' . preg_quote($placeholder, '/') . '$/m',
            static function (array $matches) use ($value): string {
                $lines = explode("\n", $value);

                return implode("\n", array_map(
                    static fn (string $line): string => $line === '' ? '' : $matches[1] . $line,
                    $lines,
                ));
            },
            $template,
        );

        return str_replace($placeholder, $value, $result ?? $template);
    }

